/* Draws one glyph at pixel (x,y) in the client's own SHM buffer, clipped
   to the client's current tile. 8x16 monochrome bitmap: one byte per row,
   MSB = leftmost pixel. `color` for set bits, background left untouched
   for clear bits (no fill -- callers that want a solid background should
   zerp_fill_rect() first, matching how a real terminal clears-then-draws
   per cell). */
static void zerp_draw_char(ZerpClient *zc, uint32_t x, uint32_t y, unsigned char c, uint32_t color) {
    const uint8_t *glyph = zerp_font_8x16[c];
    for (int row = 0; row < ZERP_FONT_HEIGHT; row++) {
        uint8_t bits = glyph[row];
        uint32_t py = y + (uint32_t)row;
        if (py >= zc->tile_h) break;
        for (int col = 0; col < ZERP_FONT_WIDTH; col++) {
            uint32_t px = x + (uint32_t)col;
            if (px >= zc->tile_w) break;
            if (bits & (0x80 >> col)) {
                zc->shm[py * zc->tile_w + px] = color;
            }
        }
    }
}

/* Draws a solid background cell then the glyph on top -- the usual case
   for a text grid (terminal, file manager listing). */
static void zerp_draw_char_bg(ZerpClient *zc, uint32_t x, uint32_t y, unsigned char c, uint32_t fg, uint32_t bg) {
    zerp_fill_rect(zc, x, y, ZERP_FONT_WIDTH, ZERP_FONT_HEIGHT, bg);
    zerp_draw_char(zc, x, y, c, fg);
}

static void zerp_draw_string(ZerpClient *zc, uint32_t x, uint32_t y, const char *s, uint32_t color) {
    uint32_t cx = x;
    while (*s) {
        zerp_draw_char(zc, cx, y, (unsigned char)*s, color);
        cx += ZERP_FONT_WIDTH;
        s++;
    }
}

static void zerp_draw_string_bg(ZerpClient *zc, uint32_t x, uint32_t y, const char *s, uint32_t fg, uint32_t bg) {
    uint32_t cx = x;
    while (*s) {
        zerp_draw_char_bg(zc, cx, y, (unsigned char)*s, fg, bg);
        cx += ZERP_FONT_WIDTH;
        s++;
    }
}

